import { describe, expect, it } from 'vitest';
import { claudePrefix, validateClaudePrefixes } from '../../src/copilot/claudePrefix';
import { createCanonicalSnapshot } from '../../src/copilot/canonicalRequest';
import type { ClaudeContentBlock, ClaudeRequest } from '../../src/relay/types';
import type { ProtocolReplayState } from '../../src/relay/replayState';

const identity = 'a'.repeat(64);
// Captured from the previous implementation: these are persisted wire-format
// contracts, not values generated by the implementation under test.
const hashes = [
  'd2966b7d9ae9da5d71a9456b48ff6541e52e13ee37308c1c7af6164452811667',
  '501591fff7df922f2a7cecf1441a16d8123823484e98aea8a98c6f660094be3b',
  '81a65d6f3ebc9a887ed980457c100bcefb8848ac5677982b0ec6815354efd4b3',
  'b6de1f451f8b6e264c44b7fcd1e6f084364acc388ebcf18034a6ab0259a054bc',
  'baa5864928b48a0c6b3e502e90381ff112b1f3a283e44f51284d6cf20482d026',
  '8d0176a41cbc6ab4c79675d1e902a77cc15c54d1d55b6a5a3a8deae4d9db6a92',
];

function request(): ClaudeRequest {
  return {
    model: 'claude', max_tokens: 4096, stream: true,
    system: [{ type: 'text', text: 'Stable system 😀\n', cache_control: { type: 'ephemeral' } }],
    tools: [{ name: 'search', description: '查找', input_schema: {
      type: 'object', properties: { cache_control: { const: 'business' } }, required: ['cache_control'],
    }, cache_control: { type: 'ephemeral', ttl: '1h' } }],
    messages: [
      { role: 'user', content: [{ type: 'text', text: 'First \\ " 😀\ud800', cache_control: { type: 'ephemeral' } }] },
      { role: 'assistant', content: [{ type: 'thinking', thinking: 'thought', signature: 'signed-1' },
        { type: 'text', text: 'checking' }, { type: 'tool_use', id: 'call_1', name: 'search', input: { cache_control: 'business' } }] },
      { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'call_1',
        content: [{ type: 'text', text: 'found', cache_control: { type: 'ephemeral' } }], cache_control: { type: 'ephemeral' } }] },
      { role: 'assistant', content: [{ type: 'redacted_thinking', data: 'opaque-2' }, { type: 'text', text: 'answer' }] },
      { role: 'user', content: 'next' },
    ],
  } as unknown as ClaudeRequest;
}

function state(wire: ClaudeRequest, index: number): ProtocolReplayState {
  return { version: 1, apiType: 'messages', identity, displayText: '',
    claude: wire.messages[index].content as ClaudeContentBlock[],
    claudePrefix: { hash: hashes[index], messageCount: index } };
}

function snapshot(...states: ProtocolReplayState[]) {
  return createCanonicalSnapshot(states.map(protocolReplay => ({ role: 'assistant',
    content: [{ kind: 'thinking', value: '', summary: [], protocolReplay }] })));
}

describe('Claude prefix hash contract', () => {
  it('preserves all previous digests, including Unicode, business keys and nested cache markers', () => {
    const wire = request();
    const original = JSON.stringify(wire);
    hashes.forEach((hash, count) => {
      expect(claudePrefix({ ...wire, messages: wire.messages.slice(0, count) })).toEqual({ hash, messageCount: count });
    });
    expect(JSON.stringify(wire)).toBe(original);
    expect(claudePrefix({ messages: [] }).hash).toBe('5e4ce7b36ba37b78a5d5f9fd08e6b7b54ba6879d651aa46ec9e1d6fa24ebe30a');
    expect(claudePrefix({ system: 'text', messages: [{ role: 'user', content: 'hi' }] }).hash)
      .toBe('4df202a39796dd3d0cd1bcf3d5052187e34ab905c5182e53bdd5c3296aec5b4b');
  });

  it('validates retained prefixes even when carriers repeat or arrive out of order', () => {
    const wire = request();
    const first = state(wire, 1), second = state(wire, 3);
    expect(() => validateClaudePrefixes(snapshot(second, first, first), wire, identity)).not.toThrow();
  });

  it.each(['system', 'tool schema', 'prior text', 'signature', 'redacted data', 'missing turn'])(
    'still rejects a changed %s', change => {
      const wire = request();
      const stored = snapshot(structuredClone(state(wire, 1)), structuredClone(state(wire, 3)));
      if (change === 'system') wire.system = 'changed';
      else if (change === 'tool schema') wire.tools![0].input_schema = { type: 'object' };
      else if (change === 'prior text') wire.messages[0].content = 'changed';
      else if (change === 'signature') (wire.messages[1].content as ClaudeContentBlock[])[0] = { type: 'thinking', thinking: 'thought', signature: 'changed' };
      else if (change === 'redacted data') (wire.messages[3].content as ClaudeContentBlock[])[0] = { type: 'redacted_thinking', data: 'changed' };
      else wire.messages.length = 3;
      expect(() => validateClaudePrefixes(stored, wire, identity)).toThrow('earlier messages changed');
    },
  );

  it('keeps missing-fingerprint errors and skips carriers from other identities or protocols', () => {
    const wire = request();
    const signed = state(wire, 1);
    expect(() => validateClaudePrefixes(snapshot({ ...signed, claudePrefix: undefined }), wire, identity)).toThrow('no prefix fingerprint');
    expect(() => validateClaudePrefixes(snapshot({ ...signed, identity: 'other' }, { ...signed, apiType: 'responses' },
      { ...signed, claude: [{ type: 'text', text: 'plain text' }] }), wire, identity)).not.toThrow();
  });

  it('supports a zero-message prefix without inventing a prior user turn', () => {
    const wire = request();
    wire.messages = [wire.messages[1]];
    expect(() => validateClaudePrefixes(snapshot(state(wire, 0)), wire, identity)).not.toThrow();
  });
});
